import axios from 'axios';

const API_BASE = process.env.REACT_APP_API_BASE || 'http://localhost:5000';

export const sendOtp = (payload) => axios.post(`${API_BASE}/send-otp`, payload);
export const verifyOtp = (payload) => axios.post(`${API_BASE}/verify-otp`, payload);
export const setPassword = (payload) => axios.post(`${API_BASE}/set-password`, payload);
export const login = (payload) => axios.post(`${API_BASE}/login`, payload);
export const planTrip = (payload) => axios.post(`${API_BASE}/plan-trip`, payload);
